// Parse LinkedIn followers page HTML
const html = $input.first().json.data;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

// Extract follower information from the page
const followers = [];

// LinkedIn uses various selectors for follower cards
const followerSelectors = [
  '.org-people-profile-card',
  '.people-search-result',
  '.follower-card',
  '[data-test-id="people-search-result"]'
];

followerSelectors.forEach(selector => {
  $(selector).each((index, element) => {
    const $element = $(element);

    // Extract profile information
    const nameElement = $element.find('.actor-name, .name, .t-16, .t-black, .t-bold').first();
    const profileLinkElement = $element.find('a[href*="/in/"]').first();
    const imageElement = $element.find('img').first();

    if (nameElement.length && profileLinkElement.length) {
      const name = nameElement.text().trim();
      const profileUrl = profileLinkElement.attr('href');
      const imageUrl = imageElement.attr('src') || '';

      // Extract LinkedIn profile ID from URL
      const profileIdMatch = profileUrl.match(/\/in\/([^\/?]+)/);
      const profileId = profileIdMatch ? profileIdMatch[1] : null;

      if (name && profileId) {
        followers.push({
          name: name,
          profileId: profileId,
          profileUrl: profileUrl.startsWith('http') ? profileUrl : `https://linkedin.com${profileUrl}`,
          imageUrl: imageUrl,
          scrapedAt: new Date().toISOString()
        });
      }
    }
  });
});

// Remove duplicates based on profileId
const uniqueFollowers = followers.filter((follower, index, self) => 
  index === self.findIndex(f => f.profileId === follower.profileId)
);

console.log(`Found ${uniqueFollowers.length} unique followers`);

return uniqueFollowers.map(follower => ({ json: follower }));

// Extract additional profile information
const html = $input.first().json.data;
const followerData = $('parse-followers').item.json;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

// Extract first name from full name
const fullName = followerData.name;
const firstName = fullName.split(' ')[0];

// Try to extract additional info from profile
const headline = $('.text-body-medium').first().text().trim() || '';
const location = $('[data-test-id="profile-location"]').text().trim() || '';

// Create personalized message based on available information
let personalizedMessage = `Hi ${firstName}! 👋\n\nThank you for following Creative Technology Collective! We're thrilled to have you join our community of innovators, creators, and tech enthusiasts.\n\n🚀 Here's what you can expect:\n• Cutting-edge insights on emerging technologies\n• Exclusive access to our community resources\n• Networking opportunities with fellow creatives\n• Early access to our workshops and events`;

// Add personalization based on headline if available
if (headline && headline.length > 0) {
  if (headline.toLowerCase().includes('developer') || headline.toLowerCase().includes('engineer')) {
    personalizedMessage += `\n\nI noticed you're in development - you'll love our technical deep-dives and coding workshops!`;
  } else if (headline.toLowerCase().includes('designer') || headline.toLowerCase().includes('creative')) {
    personalizedMessage += `\n\nAs someone in the creative field, you'll find our design-tech intersection content particularly valuable!`;
  } else if (headline.toLowerCase().includes('founder') || headline.toLowerCase().includes('entrepreneur')) {
    personalizedMessage += `\n\nGreat to have another entrepreneur in our community - our startup-focused content will be right up your alley!`;
  }
}

personalizedMessage += `\n\nFeel free to reach out if you have any questions or ideas you'd like to share. We're always excited to connect with passionate individuals like yourself!\n\nWelcome aboard! 🎉\n\nBest regards,\nThe CTC Team\n\nP.S. Check out our latest resources at creativetechnologists.nl`;

return {
  json: {
    profileId: followerData.profileId,
    profileUrl: followerData.profileUrl,
    fullName: fullName,
    firstName: firstName,
    headline: headline,
    location: location,
    message: personalizedMessage,
    timestamp: new Date().toISOString()
  }
};

// Error handling and logging
const error = $input.first();
console.error('LinkedIn Scraping Error:', error);

// Send notification to admin about the error
return {
  json: {
    status: 'error',
    message: 'LinkedIn scraping workflow encountered an error',
    error: error.json || error.message || 'Unknown error',
    timestamp: new Date().toISOString(),
    workflow: 'LinkedIn Follower Auto-DM (Web Scraping)'
  }
};
